using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows.Input;
namespace Puppeteer.App.ViewModels;
public abstract class ObservableObject : INotifyPropertyChanged { public event PropertyChangedEventHandler? PropertyChanged; protected bool Set<T>(ref T field,T value,[CallerMemberName]string? name=null){if(EqualityComparer<T>.Default.Equals(field,value))return false;field=value;PropertyChanged?.Invoke(this,new(name));return true;} protected void Raise([CallerMemberName]string? name=null)=>PropertyChanged?.Invoke(this,new(name)); }
public sealed class RelayCommand(Action<object?> execute,Func<object?,bool>? canExecute=null):ICommand { public event EventHandler? CanExecuteChanged{add=>CommandManager.RequerySuggested+=value;remove=>CommandManager.RequerySuggested-=value;} public bool CanExecute(object? p)=>canExecute?.Invoke(p)??true; public void Execute(object? p)=>execute(p); public void RaiseCanExecuteChanged()=>CommandManager.InvalidateRequerySuggested(); }
public sealed class AsyncRelayCommand(Func<object?,Task> execute,Func<object?,bool>? canExecute=null):ICommand { private bool _running; public event EventHandler? CanExecuteChanged{add=>CommandManager.RequerySuggested+=value;remove=>CommandManager.RequerySuggested-=value;} public bool CanExecute(object? p)=>!_running&&(canExecute?.Invoke(p)??true); public async void Execute(object? p){if(!CanExecute(p))return;_running=true;CommandManager.InvalidateRequerySuggested();try{await execute(p);}finally{_running=false;CommandManager.InvalidateRequerySuggested();}} }
